AddCSLuaFile("cl_init.lua");
AddCSLuaFile("shared.lua");
include("shared.lua");

function ENT:Initialize()
self:SetModel("models/props/cs_italy/orange.mdl");
self:PhysicsInit(SOLID_VPHYSICS);
self:SetMaterial("models/props_c17/FurnitureMetal001a");
self:SetColor(FS_Tomato_Color);

self:SetMoveType(MOVETYPE_VPHYSICS);
self:SetSolid(SOLID_VPHYSICS);

self:SetDTInt(0, 0);
self:SetDTBool(0, false);
if (FS_Rot_System) then
self.timer = FS_Tomato_Harvest_Time;
end;
timer.Simple( 0.01, function()
if not IsValid(self) or self:GetDTBool(0) then
return;
end

local physicsObject = self:GetPhysicsObject();
if IsValid(physicsObject) then
physicsObject:EnableMotion(true);
physicsObject:SetVelocity(self:GetUp()*2);
end;
end)
end;

function ENT:Think()
if (FS_Rot_System) then
if (!self.nextS or CurTime() >= self.nextS) then
if (self.timer > 0) then
self.timer = self.timer - 1;
end;
if (self.timer <= 0) then
self:VisualEffect();
end;
self.nextS = CurTime() + FS_Utils.SlowThinkInterval;
end;
end;

self:NextThink(CurTime() + FS_Utils.SlowThinkInterval);
return true;
end;

function ENT:OnTakeDamage(dmginfo)
self:VisualEffect();
self:EmitSound("physics/body/body_medium_break"..math.random(2, 4)..".wav");
self:Remove()
end;

function ENT:SpawnFunction(ply, trace)
local ent = ents.Create("fs_tomato");
ent:SetPos(trace.HitPos + trace.HitNormal * 8);
ent:Spawn();
ent:Activate();
return ent;
end;

function ENT:Use(activator, caller)
local curTime = CurTime();
if (!self.nextUse or curTime >= self.nextUse) then
if FS_Utils.CanPlayerUseEntity(activator, self) then
if !activator:KeyDown(IN_SPEED) then
if FS_Hunger_Enabled then
if (GAMEMODE.Version == "2.4.3") then
activator:SetSelfDarkRPVar("Energy", math.Clamp(activator:getDarkRPVar("Energy")+FS_Tomato_Hunger, 0, 100));
else
activator:setSelfDarkRPVar("Energy", math.Clamp(activator:getDarkRPVar("Energy")+FS_Tomato_Hunger, 0, 100));
end;
end;
activator:SetHealth(math.Clamp(activator:Health()+FS_Tomato_Health, 0, 100));
self:EmitSound("npc/barnacle/barnacle_crunch"..math.random(2, 3)..".wav");
self:VisualEffect();
self.nextUse = curTime + 0.5;
elseif activator:KeyDown(IN_SPEED) and FS_Salesman_Enabled then
if (activator:GetDTInt(4) < FS_Tomato_MaxHold) then
activator:SetDTInt(4, activator:GetDTInt(4)+1);
activator:EmitSound("physics/body/body_medium_impact_soft"..math.random(1, 7)..".wav");
activator:SendLua("local tab={Color(255,255,255),[[You picked up a ]],Color(175,0,0),[[Tomato]],Color(255,255,255),[[. ["..activator:GetDTInt(4).."/"..FS_Tomato_MaxHold.."] ]]} chat.AddText(unpack(tab))");
self:VisualEffect();
elseif (activator:GetDTInt(4) >= FS_Tomato_MaxHold) then
activator:SendLua("LocalPlayer():EmitSound('buttons/lightswitch2.wav')");
activator:SendLua("local tab={Color(255,255,255),[[You reached maximum amount of ]],Color(175,0,0),[[Tomatos]],Color(255,255,255),[[! ["..activator:GetDTInt(4).."/"..FS_Tomato_MaxHold.."] ]]} chat.AddText(unpack(tab))");
end;
self.nextUse = curTime + 0.5;
end;
end;
end;
end;

function ENT:VisualEffect()
local effectData = EffectData();
effectData:SetStart(self:GetPos());
effectData:SetOrigin(self:GetPos());
effectData:SetScale(8);
util.Effect("GlassImpact", effectData, true, true);
self:Remove();
end;

